// Generated from the BinGi HMS foundation package v1 (19 Nov 2026) by bhds/gen_files.py — do not edit by hand.
export type DsFile = { path: string; label: string; lang: string; body: string };
export const DS_VERSION = "1.0 · 19 Nov 2026";
export const DS_FILES: DsFile[] = [
  {"path": "web/bingi-hms.css", "label": "CSS · any web app", "lang": "css", "body": "/* BinGi HMS design foundation v1 — web (19 Nov 2026)\n   Same values as the HMS web prototype. Plain CSS variables + small component classes.\n   Use: <html class=\"bh\"> … or add class \"bh\" to the app root. Fonts: Instrument Sans, Bricolage Grotesque, Hind Siliguri. */\n\n.bh {\n  /* brand / action */\n  --bh-action: #c8232e; --bh-action-top: #d22c35; --bh-action-bottom: #ba1f2b; --bh-action-hover: #a81c27;\n  --bh-red-text: #b11c29; --bh-red-pressed: #8e1621;\n  --bh-soft: #ffecec; --bh-soft-2: #fff6f6; --bh-soft-border: #f3c4c0; --bh-blush: #ffe7e4; --bh-logo-coral: #fd413f;\n  /* neutrals */\n  --bh-canvas: #f4f6f8; --bh-surface: #ffffff; --bh-surface-alt: #fafafb;\n  --bh-ink: #0f1720; --bh-muted: #4d5664; --bh-hover: #e9edf2; --bh-track: #eef0f3;\n  --bh-line: #e3e7ec; --bh-line-strong: #c9ced6; --bh-control: #858c97; --bh-focus: #1d4ed8;\n  /* status (bg / fg) */\n  --bh-info-bg: #e8f0fe; --bh-info: #1d4ed8;\n  --bh-success-bg: #e5f5ec; --bh-success: #16693a;\n  --bh-warning-bg: #fdf3d9; --bh-warning: #7a4a0b;\n  --bh-danger-bg: #fdecec; --bh-danger: #b42318;\n  --bh-violet-bg: #f1edff; --bh-violet: #5b45c9;\n  --bh-neutral-bg: #eef0f3; --bh-neutral: #4d5664;\n  --bh-orange: #c2410c;\n  /* type */\n  --bh-font: \"Instrument Sans\", \"Instrument Sans Variable\", \"Hind Siliguri\", system-ui, sans-serif;\n  --bh-font-heading: \"Bricolage Grotesque\", \"Bricolage Grotesque Variable\", \"Hind Siliguri\", system-ui, sans-serif;\n  /* shape */\n  --bh-r-chip: 6px; --bh-r-control: 12px; --bh-r-tile: 16px; --bh-r-card: 20px; --bh-r-sheet: 24px;\n  --bh-h-main: 44px; --bh-h-row: 36px;\n  --bh-shadow-action: 0 6px 16px rgb(200 35 46 / 0.24);\n  --bh-shadow-float: 0 16px 40px -12px rgb(0 0 0 / 0.25);\n  /* motion */\n  --bh-ease-pop: cubic-bezier(0.2, 0.9, 0.3, 1.15); --bh-ease-sheet: cubic-bezier(0.22, 1, 0.36, 1);\n\n  background: var(--bh-canvas); color: var(--bh-ink); font-family: var(--bh-font); font-size: 14px; line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n}\n.bh :is(h1, h2, h3) { font-family: var(--bh-font-heading); letter-spacing: -0.02em; }\n.bh :focus-visible { outline: 2px solid var(--bh-focus); outline-offset: 2px; }\n.bh .bh-num { font-variant-numeric: tabular-nums; }\n\n/* Buttons — one red main action per screen; white bordered for the rest */\n.bh-btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; height: var(--bh-h-main); padding: 0 16px;\n  border-radius: var(--bh-r-control); border: 1px solid var(--bh-line); background: var(--bh-surface); color: var(--bh-ink);\n  font: 600 14.5px/1 var(--bh-font); white-space: nowrap; cursor: pointer; transition: background-color .15s ease, transform .12s ease, box-shadow .15s ease; }\n.bh-btn:hover { background: var(--bh-hover); }\n.bh-btn:active { transform: scale(0.985); }\n.bh-btn:disabled { opacity: .45; pointer-events: none; }\n.bh-btn--main { border: 0; padding: 0 20px; color: #fff; background-color: var(--bh-action);\n  background-image: linear-gradient(180deg, var(--bh-action-top), var(--bh-action) 55%, var(--bh-action-bottom)); box-shadow: var(--bh-shadow-action); }\n.bh-btn--main:hover { background-image: linear-gradient(180deg, var(--bh-action), var(--bh-action-hover)); }\n.bh-btn--main:disabled { box-shadow: none; filter: grayscale(.35); }\n.bh-btn--row { height: var(--bh-h-row); padding: 0 12px; font-size: 13.5px; }\n.bh-btn--text { border: 0; background: none; color: var(--bh-red-text); height: auto; padding: 0; }\n\n/* Segmented control / view toggle */\n.bh-seg { display: inline-flex; gap: 2px; padding: 4px; border: 1px solid var(--bh-line); border-radius: var(--bh-r-control); background: var(--bh-surface); }\n.bh-seg > button { height: 36px; padding: 0 12px; border: 0; border-radius: 10px; background: none; color: var(--bh-muted); font: 600 13.5px/1 var(--bh-font); cursor: pointer; }\n.bh-seg > [aria-checked=\"true\"], .bh-seg > [aria-selected=\"true\"] { background: var(--bh-soft); color: var(--bh-action); }\n\n/* Underline tabs (module sections) */\n.bh-tabs { display: flex; gap: 24px; border-bottom: 1px solid var(--bh-line); }\n.bh-tabs > * { margin-bottom: -1px; padding-bottom: 10px; border-bottom: 2px solid transparent; color: var(--bh-muted); font: 600 14.5px/1.2 var(--bh-font); background: none; border-top: 0; border-left: 0; border-right: 0; cursor: pointer; }\n.bh-tabs > [aria-selected=\"true\"], .bh-tabs > [aria-current=\"page\"] { border-bottom-color: var(--bh-action); color: var(--bh-action); }\n\n/* Card, tile, inputs */\n.bh-card { background: var(--bh-surface); border: 1px solid var(--bh-line); border-radius: var(--bh-r-card); }\n.bh-card--selected { border-color: var(--bh-soft-border); }\n.bh-input, .bh-select { height: var(--bh-h-main); width: 100%; padding: 0 12px; border: 1px solid var(--bh-line); border-radius: var(--bh-r-control);\n  background: var(--bh-surface); color: var(--bh-ink); font: 400 14px var(--bh-font); outline: none; }\n.bh-input:focus, .bh-select:focus { border-color: var(--bh-action); }\n\n/* Status pill — booking / payment / room / maintenance each its own pill */\n.bh-pill { display: inline-flex; align-items: center; gap: 6px; padding: 2px 8px; border-radius: var(--bh-r-chip); font: 600 12.5px/1.5 var(--bh-font); white-space: nowrap; }\n.bh-pill::before { content: \"\"; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }\n.bh-pill--info { background: var(--bh-info-bg); color: var(--bh-info); }\n.bh-pill--success { background: var(--bh-success-bg); color: var(--bh-success); }\n.bh-pill--warning { background: var(--bh-warning-bg); color: var(--bh-warning); }\n.bh-pill--danger { background: var(--bh-danger-bg); color: var(--bh-danger); }\n.bh-pill--violet { background: var(--bh-violet-bg); color: var(--bh-violet); }\n.bh-pill--neutral { background: var(--bh-neutral-bg); color: var(--bh-neutral); }\n\n/* Banner, toast, menu */\n.bh-banner { display: flex; align-items: center; gap: 10px; padding: 12px 14px; border-radius: var(--bh-r-tile); border: 1px solid #f1dfb8; background: #fdf8ec; color: #6b4309; }\n.bh-banner--blue { border-color: #cfdcf7; background: #eef3fd; color: #1e3a8a; }\n.bh-banner--green { border-color: #cde9d8; background: #eef8f2; color: #14532d; }\n.bh-toast { display: inline-flex; align-items: center; gap: 8px; padding: 10px 16px; border-radius: var(--bh-r-control); background: var(--bh-ink); color: #fff; font: 500 14px var(--bh-font); animation: bh-up .18s ease-out both; }\n.bh-menu { background: var(--bh-surface); border: 1px solid var(--bh-line); border-radius: var(--bh-r-tile); box-shadow: var(--bh-shadow-float); padding: 6px; animation: bh-pop .14s var(--bh-ease-pop) both; }\n\n/* Motion — page change is a fade only (no zoom, no slide) */\n.bh-page-in { animation: bh-fade 150ms ease-out both; }\n@keyframes bh-fade { from { opacity: 0; } to { opacity: 1; } }\n@keyframes bh-pop { from { opacity: 0; transform: scale(.96) translateY(-4px); } to { opacity: 1; transform: none; } }\n@keyframes bh-up { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: none; } }\n@keyframes bh-sheet { from { transform: translateY(100%); } to { transform: none; } }\n@media (prefers-reduced-motion: reduce) { .bh *, .bh { animation: none !important; transition: none !important; } }\n"},
  {"path": "web/tailwind-theme.css", "label": "Tailwind v4 @theme", "lang": "css", "body": "/* BinGi HMS foundation v1 — Tailwind v4 theme (same values as the HMS web prototype).\n   @import \"tailwindcss\"; then paste this. Classes: bg-hms-canvas, text-hms-ink, border-hms-line, rounded-control … */\n@theme {\n  --color-hms-action: #c8232e;\n  --color-hms-action-top: #d22c35;\n  --color-hms-action-bottom: #ba1f2b;\n  --color-hms-action-hover: #a81c27;\n  --color-hms-red: #b11c29;\n  --color-hms-red-pressed: #8e1621;\n  --color-hms-soft: #ffecec;\n  --color-hms-soft-2: #fff6f6;\n  --color-hms-soft-border: #f3c4c0;\n  --color-hms-blush: #ffe7e4;\n  --color-hms-brand: #fd413f;\n  --color-hms-canvas: #f4f6f8;\n  --color-hms-surface: #ffffff;\n  --color-hms-ink: #0f1720;\n  --color-hms-muted: #4d5664;\n  --color-hms-hover: #e9edf2;\n  --color-hms-track: #eef0f3;\n  --color-hms-line: #e3e7ec;\n  --color-hms-line-strong: #c9ced6;\n  --color-hms-input: #858c97;\n  --color-hms-focus: #1d4ed8;\n  --color-hms-info-bg: #e8f0fe;    --color-hms-info: #1d4ed8;\n  --color-hms-success-bg: #e5f5ec; --color-hms-success: #16693a;\n  --color-hms-warning-bg: #fdf3d9; --color-hms-warning: #7a4a0b;\n  --color-hms-danger-bg: #fdecec;  --color-hms-danger: #b42318;\n  --color-hms-violet-bg: #f1edff;  --color-hms-violet: #5b45c9;\n  --color-hms-neutral-bg: #eef0f3; --color-hms-neutral: #4d5664;\n  --font-sans: \"Instrument Sans Variable\", \"Hind Siliguri\", system-ui, sans-serif;\n  --font-heading: \"Bricolage Grotesque Variable\", \"Hind Siliguri\", system-ui, sans-serif;\n  --radius-chip: 6px;\n  --radius-control: 12px;\n  --radius-tile: 16px;\n  --radius-card: 20px;\n  --radius-sheet: 24px;\n  --shadow-action: 0 6px 16px rgb(200 35 46 / 0.24);\n  --shadow-float: 0 16px 40px -12px rgb(0 0 0 / 0.25);\n}\n/* Motion used by react/bingi-ui.tsx (toast) */\n@keyframes bh-up { from { opacity: 0; transform: translate(-50%, 8px); } to { opacity: 1; transform: translate(-50%, 0); } }\n"},
  {"path": "react/bingi-ui.tsx", "label": "React components (Tailwind)", "lang": "tsx", "body": "// BinGi HMS foundation v1 — React + Tailwind v4 components (19 Nov 2026)\n// Needs web/tailwind-theme.css (the hms-* tokens) and the three fonts. Same look as the HMS web prototype.\n// Copy into src/ui/bingi-ui.tsx. No dependencies besides React (icons: pass any element, e.g. lucide-react).\nimport { useEffect, useState, type ButtonHTMLAttributes, type ReactNode } from \"react\";\n\nconst cx = (...c: (string | false | null | undefined)[]) => c.filter(Boolean).join(\" \");\n\n/* Buttons — one red main action per screen; everything else white with a 1 px border. */\nconst base = \"inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-[12px] font-semibold transition-[background-color,transform,box-shadow] duration-150 active:scale-[0.985] disabled:pointer-events-none disabled:opacity-45\";\ntype BtnProps = ButtonHTMLAttributes<HTMLButtonElement> & { icon?: ReactNode; size?: \"main\" | \"row\" };\nexport function MainButton({ icon, size = \"main\", className, children, ...p }: BtnProps) {\n  return (\n    <button {...p} className={cx(base, size === \"main\" ? \"h-11 px-5 text-[14.5px]\" : \"h-9 px-3 text-[13.5px]\",\n      \"bg-hms-action bg-[linear-gradient(180deg,#d22c35,#c8232e_55%,#ba1f2b)] text-white shadow-action hover:bg-[linear-gradient(180deg,#c8232e,#a81c27)] disabled:shadow-none\", className)}>\n      {icon}{children}\n    </button>\n  );\n}\nexport function Button({ icon, size = \"main\", className, children, ...p }: BtnProps) {\n  return (\n    <button {...p} className={cx(base, size === \"main\" ? \"h-11 px-4 text-[14.5px]\" : \"h-9 px-3 text-[13.5px]\",\n      \"border border-hms-line bg-white text-hms-ink hover:bg-hms-hover\", className)}>\n      {icon}{children}\n    </button>\n  );\n}\n\n/* Status pill — booking / payment / room / maintenance each get their own pill. */\nexport type Tone = \"info\" | \"success\" | \"warning\" | \"danger\" | \"violet\" | \"neutral\";\nconst TONE: Record<Tone, string> = {\n  info: \"bg-hms-info-bg text-hms-info\", success: \"bg-hms-success-bg text-hms-success\", warning: \"bg-hms-warning-bg text-hms-warning\",\n  danger: \"bg-hms-danger-bg text-hms-danger\", violet: \"bg-hms-violet-bg text-hms-violet\", neutral: \"bg-hms-neutral-bg text-hms-neutral\",\n};\nexport function StatusPill({ tone = \"neutral\", children }: { tone?: Tone; children: ReactNode }) {\n  return <span className={cx(\"inline-flex items-center gap-1.5 whitespace-nowrap rounded-chip px-2 py-0.5 text-[12.5px] font-semibold\", TONE[tone])}><span className=\"size-1.5 rounded-full bg-current\" />{children}</span>;\n}\n/** Fixed words → fixed tones, the same in every module. */\nexport const STATUS_TONE: Record<string, Tone> = {\n  Confirmed: \"info\", \"In house\": \"success\", \"Checked out\": \"neutral\", Cancelled: \"danger\", \"No-show\": \"danger\",\n  Pending: \"warning\", Cleaning: \"info\", \"Awaiting inspection\": \"violet\", Ready: \"success\",\n  Paid: \"success\", \"Partly paid\": \"warning\", Due: \"danger\", \"Refund due\": \"violet\",\n};\n\n/* Segmented control — selected = soft red bg + red text. */\nexport function Segmented<T extends string>({ items, value, onChange, label }: { items: [T, string][]; value: T; onChange: (v: T) => void; label: string }) {\n  return (\n    <div role=\"radiogroup\" aria-label={label} className=\"inline-flex gap-0.5 rounded-control border border-hms-line bg-white p-1\">\n      {items.map(([v, l]) => (\n        <button key={v} role=\"radio\" aria-checked={v === value} onClick={() => onChange(v)}\n          className={cx(\"h-9 rounded-[10px] px-3 text-[13.5px] font-semibold transition-colors\", v === value ? \"bg-hms-soft text-hms-action\" : \"text-hms-muted hover:text-hms-ink\")}>{l}</button>\n      ))}\n    </div>\n  );\n}\n\n/* Underline tabs for module sections. */\nexport function Tabs<T extends string>({ items, value, onChange, label }: { items: [T, string][]; value: T; onChange: (v: T) => void; label: string }) {\n  return (\n    <div role=\"tablist\" aria-label={label} className=\"flex gap-6 border-b border-hms-line\">\n      {items.map(([v, l]) => (\n        <button key={v} role=\"tab\" aria-selected={v === value} onClick={() => onChange(v)}\n          className={cx(\"-mb-px border-b-2 pb-2.5 text-[14.5px] font-semibold\", v === value ? \"border-hms-action text-hms-action\" : \"border-transparent text-hms-muted hover:text-hms-ink\")}>{l}</button>\n      ))}\n    </div>\n  );\n}\n\n/* Card — white, 1 px line, 20 px corners, no shadow. Never a card in a card. */\nexport function Card({ children, selected, className, onClick }: { children: ReactNode; selected?: boolean; className?: string; onClick?: () => void }) {\n  const C = onClick ? \"button\" : \"div\";\n  return <C onClick={onClick} className={cx(\"block rounded-card border bg-white p-4 text-left\", selected ? \"border-hms-soft-border\" : \"border-hms-line\", onClick && \"hover:border-hms-line-strong\", className)}>{children}</C>;\n}\n\n/* Stat tile — tinted 44 px icon square + label + number. */\nexport function StatTile({ icon, label, value, sub, tone = \"info\", selected, onClick }: { icon: ReactNode; label: string; value: string; sub?: string; tone?: Tone; selected?: boolean; onClick?: () => void }) {\n  return (\n    <Card onClick={onClick} selected={selected} className=\"flex items-center gap-3\">\n      <span className={cx(\"grid size-11 shrink-0 place-items-center rounded-tile\", TONE[tone])}>{icon}</span>\n      <span className=\"min-w-0\"><span className=\"block text-[12.5px] text-hms-muted\">{label}</span><b className=\"block truncate text-[22px] leading-tight tabular-nums\">{value}</b>{sub && <span className=\"block truncate text-[12px] text-hms-muted\">{sub}</span>}</span>\n    </Card>\n  );\n}\n\n/* Banner — amber needs attention, blue in progress, green done. */\nconst BAN = { amber: \"border-[#f1dfb8] bg-[#fdf8ec] text-[#6b4309]\", blue: \"border-[#cfdcf7] bg-[#eef3fd] text-[#1e3a8a]\", green: \"border-[#cde9d8] bg-[#eef8f2] text-[#14532d]\" };\nexport function Banner({ kind = \"amber\", icon, children, action }: { kind?: keyof typeof BAN; icon?: ReactNode; children: ReactNode; action?: ReactNode }) {\n  return <div className={cx(\"flex items-center gap-2.5 rounded-tile border px-4 py-3 text-[14px]\", BAN[kind])}>{icon}<span className=\"min-w-0 flex-1\">{children}</span>{action}</div>;\n}\n\n/* Avatar — initials on soft red; dashed when nobody is assigned. */\nexport function Avatar({ name, size = 40 }: { name?: string; size?: number }) {\n  const ini = name ? name.split(/\\s+/).map((p) => p[0]).slice(0, 2).join(\"\").toUpperCase() : \"\";\n  return <span style={{ width: size, height: size, fontSize: size * 0.33 }} className={cx(\"grid shrink-0 place-items-center rounded-full font-bold\", name ? \"bg-hms-soft text-hms-action\" : \"border border-dashed border-hms-line-strong text-hms-muted\")}>{ini || \"?\"}</span>;\n}\n\n/* Progress — 6 px, track + blue fill. */\nexport function Progress({ value, label }: { value: number; label: string }) {\n  return <div role=\"progressbar\" aria-label={label} aria-valuenow={value} aria-valuemin={0} aria-valuemax={100} className=\"h-1.5 overflow-hidden rounded-full bg-hms-track\"><div className=\"h-full rounded-full bg-hms-focus transition-[width] duration-300\" style={{ width: `${value}%` }} /></div>;\n}\n\n/* Toast — dark, bottom centre, 2.4 s. */\nexport function useToast() {\n  const [text, setText] = useState(\"\");\n  useEffect(() => { if (!text) return; const t = setTimeout(() => setText(\"\"), 2400); return () => clearTimeout(t); }, [text]);\n  const node = text ? <div role=\"status\" className=\"fixed bottom-6 left-1/2 z-50 flex -translate-x-1/2 items-center gap-2 rounded-control bg-hms-ink px-4 py-2.5 text-[14px] font-medium text-white shadow-float motion-safe:animate-[bh-up_.18s_ease-out]\">✓ {text}</div> : null;\n  return { toast: setText, node };\n}\n"},
  {"path": "tokens/bingi-hms.tokens.json", "label": "Design tokens (W3C JSON)", "lang": "json", "body": "{\n  \"$description\": \"BinGi HMS design foundation v1 (19 Nov 2026). Source: HMS web prototype (BINGI-WEB-theme-, commit c994c50) = BinGi Pearl tokens + live-HMS button foundation. W3C Design Tokens format.\",\n  \"color\": {\n    \"brand\": {\n      \"action\":        { \"$type\": \"color\", \"$value\": \"#C8232E\", \"$description\": \"Main action red (live HMS). Primary button middle stop, active tab text, selected segment text.\" },\n      \"action-top\":    { \"$type\": \"color\", \"$value\": \"#D22C35\", \"$description\": \"Primary button gradient top\" },\n      \"action-bottom\": { \"$type\": \"color\", \"$value\": \"#BA1F2B\", \"$description\": \"Primary button gradient bottom\" },\n      \"action-hover\":  { \"$type\": \"color\", \"$value\": \"#A81C27\", \"$description\": \"Primary button hover / pressed bottom\" },\n      \"red-text\":      { \"$type\": \"color\", \"$value\": \"#B11C29\", \"$description\": \"Red text and links on white (6.85:1). Brand red — use sparingly.\" },\n      \"red-pressed\":   { \"$type\": \"color\", \"$value\": \"#8E1621\" },\n      \"soft\":          { \"$type\": \"color\", \"$value\": \"#FFECEC\", \"$description\": \"Selected segment / active filter background (text #C8232E)\" },\n      \"soft-2\":        { \"$type\": \"color\", \"$value\": \"#FFF6F6\", \"$description\": \"Selected tile / row background\" },\n      \"soft-border\":   { \"$type\": \"color\", \"$value\": \"#F3C4C0\", \"$description\": \"Border of a selected card or chip\" },\n      \"blush\":         { \"$type\": \"color\", \"$value\": \"#FFE7E4\", \"$description\": \"Avatars, small accent chips (text #8E1621)\" },\n      \"logo-coral\":    { \"$type\": \"color\", \"$value\": \"#FD413F\", \"$description\": \"Logo and large art only. Never small text.\" }\n    },\n    \"neutral\": {\n      \"canvas\":       { \"$type\": \"color\", \"$value\": \"#F4F6F8\", \"$description\": \"App background (Pearl)\" },\n      \"surface\":      { \"$type\": \"color\", \"$value\": \"#FFFFFF\", \"$description\": \"Cards, sheets, sidebar, inputs\" },\n      \"surface-alt\":  { \"$type\": \"color\", \"$value\": \"#FAFAFB\", \"$description\": \"Table header, quiet rows\" },\n      \"ink\":          { \"$type\": \"color\", \"$value\": \"#0F1720\", \"$description\": \"Main text (16.7:1)\" },\n      \"muted\":        { \"$type\": \"color\", \"$value\": \"#4D5664\", \"$description\": \"Secondary text (7.4:1 on white)\" },\n      \"hover\":        { \"$type\": \"color\", \"$value\": \"#E9EDF2\", \"$description\": \"Hover / pressed fill, muted surface\" },\n      \"track\":        { \"$type\": \"color\", \"$value\": \"#EEF0F3\", \"$description\": \"Progress track, neutral pill\" },\n      \"line\":         { \"$type\": \"color\", \"$value\": \"#E3E7EC\", \"$description\": \"Card border, dividers\" },\n      \"line-strong\":  { \"$type\": \"color\", \"$value\": \"#C9CED6\", \"$description\": \"Hovered card border, dashed empty avatar\" },\n      \"control\":      { \"$type\": \"color\", \"$value\": \"#858C97\", \"$description\": \"Input/select border when a 3:1 edge is required\" },\n      \"toast\":        { \"$type\": \"color\", \"$value\": \"#0F1720\", \"$description\": \"Toast background (white text)\" }\n    },\n    \"focus\": { \"$type\": \"color\", \"$value\": \"#1D4ED8\", \"$description\": \"Focus ring (Ocean Blue) — never red, so it never looks like an error\" },\n    \"status\": {\n      \"info-bg\":    { \"$type\": \"color\", \"$value\": \"#E8F0FE\" }, \"info-fg\":    { \"$type\": \"color\", \"$value\": \"#1D4ED8\", \"$description\": \"Confirmed, Cleaning, Website source\" },\n      \"success-bg\": { \"$type\": \"color\", \"$value\": \"#E5F5EC\" }, \"success-fg\": { \"$type\": \"color\", \"$value\": \"#16693A\", \"$description\": \"In house, Paid, Ready, Room clean\" },\n      \"warning-bg\": { \"$type\": \"color\", \"$value\": \"#FDF3D9\" }, \"warning-fg\": { \"$type\": \"color\", \"$value\": \"#7A4A0B\", \"$description\": \"Pending, Partly paid, Guest arriving, Agent\" },\n      \"danger-bg\":  { \"$type\": \"color\", \"$value\": \"#FDECEC\" }, \"danger-fg\":  { \"$type\": \"color\", \"$value\": \"#B42318\", \"$description\": \"Due, Cancelled, No-show, Overdue, High priority\" },\n      \"violet-bg\":  { \"$type\": \"color\", \"$value\": \"#F1EDFF\" }, \"violet-fg\":  { \"$type\": \"color\", \"$value\": \"#5B45C9\", \"$description\": \"Awaiting inspection, Refund due, OTA\" },\n      \"neutral-bg\": { \"$type\": \"color\", \"$value\": \"#EEF0F3\" }, \"neutral-fg\": { \"$type\": \"color\", \"$value\": \"#4D5664\", \"$description\": \"Checked out, Low priority, Walk-in\" },\n      \"orange-fg\":  { \"$type\": \"color\", \"$value\": \"#C2410C\", \"$description\": \"Needs cleaning, Leaves today\" },\n      \"dot-pending\":   { \"$type\": \"color\", \"$value\": \"#D97706\" },\n      \"dot-cleaning\":  { \"$type\": \"color\", \"$value\": \"#2563EB\" },\n      \"dot-review\":    { \"$type\": \"color\", \"$value\": \"#6D5BD0\" },\n      \"dot-ready\":     { \"$type\": \"color\", \"$value\": \"#16A34A\" }\n    },\n    \"banner\": {\n      \"amber-bg\": { \"$type\": \"color\", \"$value\": \"#FDF8EC\" }, \"amber-line\": { \"$type\": \"color\", \"$value\": \"#F1DFB8\" }, \"amber-fg\": { \"$type\": \"color\", \"$value\": \"#6B4309\" },\n      \"blue-bg\":  { \"$type\": \"color\", \"$value\": \"#EEF3FD\" }, \"blue-line\":  { \"$type\": \"color\", \"$value\": \"#CFDCF7\" }, \"blue-fg\":  { \"$type\": \"color\", \"$value\": \"#1E3A8A\" },\n      \"green-bg\": { \"$type\": \"color\", \"$value\": \"#EEF8F2\" }, \"green-line\": { \"$type\": \"color\", \"$value\": \"#CDE9D8\" }, \"green-fg\": { \"$type\": \"color\", \"$value\": \"#14532D\" }\n    },\n    \"chart\": { \"$type\": \"color\", \"$value\": [\"#B11C29\", \"#1D4ED8\", \"#0E9F6E\", \"#F59E0B\", \"#0B2235\"] }\n  },\n  \"font\": {\n    \"body\":    { \"$type\": \"fontFamily\", \"$value\": [\"Instrument Sans\", \"Hind Siliguri\", \"system-ui\", \"sans-serif\"] },\n    \"heading\": { \"$type\": \"fontFamily\", \"$value\": [\"Bricolage Grotesque\", \"Hind Siliguri\", \"system-ui\", \"sans-serif\"], \"$description\": \"h1–h3 only, letter-spacing -0.02em\" },\n    \"bangla\":  { \"$type\": \"fontFamily\", \"$value\": [\"Hind Siliguri\"] }\n  },\n  \"type\": {\n    \"page-title\":  { \"$type\": \"typography\", \"$value\": { \"fontSize\": \"24px\", \"fontWeight\": 700, \"lineHeight\": 1.25, \"letterSpacing\": \"-0.01em\", \"fontFamily\": \"{font.heading}\" } },\n    \"section\":     { \"$type\": \"typography\", \"$value\": { \"fontSize\": \"18px\", \"fontWeight\": 700, \"lineHeight\": 1.3,  \"fontFamily\": \"{font.heading}\" } },\n    \"card-title\":  { \"$type\": \"typography\", \"$value\": { \"fontSize\": \"17px\", \"fontWeight\": 700, \"lineHeight\": 1.3 } },\n    \"number\":      { \"$type\": \"typography\", \"$value\": { \"fontSize\": \"22px\", \"fontWeight\": 700, \"lineHeight\": 1.15, \"fontFeature\": \"tnum\" } },\n    \"body\":        { \"$type\": \"typography\", \"$value\": { \"fontSize\": \"14px\", \"fontWeight\": 400, \"lineHeight\": 1.5 } },\n    \"body-strong\": { \"$type\": \"typography\", \"$value\": { \"fontSize\": \"14.5px\", \"fontWeight\": 600, \"lineHeight\": 1.4 } },\n    \"label\":       { \"$type\": \"typography\", \"$value\": { \"fontSize\": \"13.5px\", \"fontWeight\": 600, \"lineHeight\": 1.3 } },\n    \"meta\":        { \"$type\": \"typography\", \"$value\": { \"fontSize\": \"12.5px\", \"fontWeight\": 500, \"lineHeight\": 1.35 } },\n    \"overline\":    { \"$type\": \"typography\", \"$value\": { \"fontSize\": \"12px\", \"fontWeight\": 600, \"lineHeight\": 1.3, \"letterSpacing\": \"0.04em\", \"textTransform\": \"uppercase\" } }\n  },\n  \"space\": { \"1\": \"4px\", \"2\": \"8px\", \"3\": \"12px\", \"4\": \"16px\", \"5\": \"20px\", \"6\": \"24px\", \"8\": \"32px\", \"10\": \"40px\", \"page-x-phone\": \"16px\", \"page-x-desktop\": \"24px\" },\n  \"radius\": { \"chip\": \"6px\", \"control\": \"12px\", \"button\": \"12px\", \"input\": \"12px\", \"tile\": \"16px\", \"card\": \"20px\", \"sheet\": \"24px\", \"pill\": \"999px\" },\n  \"size\": { \"button-main\": \"44px\", \"button-row\": \"36px\", \"button-compact\": \"40px\", \"input\": \"44px\", \"icon-button\": \"44px\", \"tap-min\": \"44px\", \"avatar\": \"40px\", \"avatar-sm\": \"32px\", \"tab-bar\": \"64px\" },\n  \"shadow\": {\n    \"action\": { \"$type\": \"shadow\", \"$value\": \"0 6px 16px rgba(200,35,46,0.24)\", \"$description\": \"Primary button only\" },\n    \"card\":   { \"$type\": \"shadow\", \"$value\": \"none\", \"$description\": \"Cards are flat: 1px line border, no shadow\" },\n    \"float\":  { \"$type\": \"shadow\", \"$value\": \"0 16px 40px -12px rgba(0,0,0,0.25)\", \"$description\": \"Menus, popovers, popup cards\" },\n    \"sheet\":  { \"$type\": \"shadow\", \"$value\": \"0 24px 48px -20px rgba(22,24,29,0.25)\" }\n  },\n  \"motion\": {\n    \"page\":    { \"$type\": \"transition\", \"$value\": { \"duration\": \"150ms\", \"timingFunction\": \"ease-out\" }, \"$description\": \"Page change = opacity fade only. No zoom, no slide.\" },\n    \"press\":   { \"$type\": \"transition\", \"$value\": { \"duration\": \"120ms\", \"timingFunction\": \"ease\" }, \"$description\": \"Button pressed = scale 0.985\" },\n    \"pop\":     { \"$type\": \"transition\", \"$value\": { \"duration\": \"140ms\", \"timingFunction\": \"cubic-bezier(0.2,0.9,0.3,1.15)\" }, \"$description\": \"Menu/popover: opacity + 4px drop, scale 0.96 → 1\" },\n    \"sheet\":   { \"$type\": \"transition\", \"$value\": { \"duration\": \"220ms\", \"timingFunction\": \"cubic-bezier(0.22,1,0.36,1)\" }, \"$description\": \"Side panel / bottom sheet slides in\" },\n    \"toast\":   { \"$type\": \"transition\", \"$value\": { \"duration\": \"180ms\", \"timingFunction\": \"ease-out\" }, \"$description\": \"Toast rises 12px + fades; stays 2.4s\" },\n    \"reduced\": { \"$description\": \"With reduced motion: no animation at all\" }\n  }\n}\n"},
  {"path": "flutter/lib/bingi_theme.dart", "label": "Flutter theme + widgets", "lang": "dart", "body": "// BinGi HMS design foundation v1 — Flutter (19 Nov 2026)\n// Same values as the HMS web prototype (BinGi Pearl + live-HMS buttons).\n// Copy this file into lib/ and use:  MaterialApp(theme: BinGiTheme.light(), ...)\n// Fonts (pubspec.yaml → flutter/fonts or google_fonts): Instrument Sans (body), Bricolage Grotesque (headings), Hind Siliguri (Bangla).\nimport 'package:flutter/material.dart';\n\n// ───────────────────────── Colors ─────────────────────────\nclass BinGiColors {\n  BinGiColors._();\n  // Brand / action (use red sparingly: one main action per screen)\n  static const action = Color(0xFFC8232E);\n  static const actionTop = Color(0xFFD22C35);\n  static const actionBottom = Color(0xFFBA1F2B);\n  static const actionHover = Color(0xFFA81C27);\n  static const redText = Color(0xFFB11C29); // red text & links on white\n  static const redPressed = Color(0xFF8E1621);\n  static const soft = Color(0xFFFFECEC); // selected segment / active filter bg\n  static const soft2 = Color(0xFFFFF6F6); // selected tile bg\n  static const softBorder = Color(0xFFF3C4C0);\n  static const blush = Color(0xFFFFE7E4); // avatars\n  static const logoCoral = Color(0xFFFD413F); // logo / large art only\n\n  // Neutrals\n  static const canvas = Color(0xFFF4F6F8);\n  static const surface = Color(0xFFFFFFFF);\n  static const surfaceAlt = Color(0xFFFAFAFB);\n  static const ink = Color(0xFF0F1720);\n  static const muted = Color(0xFF4D5664);\n  static const hover = Color(0xFFE9EDF2);\n  static const track = Color(0xFFEEF0F3);\n  static const line = Color(0xFFE3E7EC);\n  static const lineStrong = Color(0xFFC9CED6);\n  static const control = Color(0xFF858C97);\n  static const focus = Color(0xFF1D4ED8);\n\n  // Status (bg, fg) — booking, payment, room and task states each use these the same way everywhere\n  static const infoBg = Color(0xFFE8F0FE), infoFg = Color(0xFF1D4ED8);\n  static const successBg = Color(0xFFE5F5EC), successFg = Color(0xFF16693A);\n  static const warningBg = Color(0xFFFDF3D9), warningFg = Color(0xFF7A4A0B);\n  static const dangerBg = Color(0xFFFDECEC), dangerFg = Color(0xFFB42318);\n  static const violetBg = Color(0xFFF1EDFF), violetFg = Color(0xFF5B45C9);\n  static const neutralBg = Color(0xFFEEF0F3), neutralFg = Color(0xFF4D5664);\n  static const orangeFg = Color(0xFFC2410C);\n  // Housekeeping step dots\n  static const dotPending = Color(0xFFD97706), dotCleaning = Color(0xFF2563EB), dotReview = Color(0xFF6D5BD0), dotReady = Color(0xFF16A34A);\n  // Banners\n  static const amberBg = Color(0xFFFDF8EC), amberLine = Color(0xFFF1DFB8), amberFg = Color(0xFF6B4309);\n  static const blueBg = Color(0xFFEEF3FD), blueLine = Color(0xFFCFDCF7), blueFg = Color(0xFF1E3A8A);\n  static const greenBg = Color(0xFFEEF8F2), greenLine = Color(0xFFCDE9D8), greenFg = Color(0xFF14532D);\n  static const toast = Color(0xFF0F1720);\n  static const charts = [Color(0xFFB11C29), Color(0xFF1D4ED8), Color(0xFF0E9F6E), Color(0xFFF59E0B), Color(0xFF0B2235)];\n\n  static const actionGradient = LinearGradient(\n    begin: Alignment.topCenter, end: Alignment.bottomCenter,\n    colors: [actionTop, action, actionBottom], stops: [0, .55, 1],\n  );\n}\n\n// ───────────────────────── Spacing / radius / size ─────────────────────────\nclass BinGiSpace {\n  BinGiSpace._();\n  static const s1 = 4.0, s2 = 8.0, s3 = 12.0, s4 = 16.0, s5 = 20.0, s6 = 24.0, s8 = 32.0, s10 = 40.0;\n  static const pagePhone = 16.0, pageDesktop = 24.0;\n}\n\nclass BinGiRadius {\n  BinGiRadius._();\n  static const chip = 6.0, control = 12.0, button = 12.0, input = 12.0, tile = 16.0, card = 20.0, sheet = 24.0, pill = 999.0;\n  static BorderRadius all(double r) => BorderRadius.circular(r);\n}\n\nclass BinGiSize {\n  BinGiSize._();\n  static const buttonMain = 44.0, buttonRow = 36.0, buttonCompact = 40.0, input = 44.0, iconButton = 44.0, tapMin = 44.0;\n  static const avatar = 40.0, avatarSm = 32.0, tabBar = 64.0;\n}\n\nclass BinGiShadow {\n  BinGiShadow._();\n  static const action = [BoxShadow(color: Color(0x3DC8232E), offset: Offset(0, 6), blurRadius: 16)];\n  static const float = [BoxShadow(color: Color(0x40000000), offset: Offset(0, 16), blurRadius: 40, spreadRadius: -12)];\n  static const sheet = [BoxShadow(color: Color(0x4016181D), offset: Offset(0, 24), blurRadius: 48, spreadRadius: -20)];\n  // Cards are flat: border BinGiColors.line, no shadow.\n}\n\nclass BinGiMotion {\n  BinGiMotion._();\n  static const page = Duration(milliseconds: 150); // fade only — no zoom, no slide\n  static const press = Duration(milliseconds: 120); // scale 0.985\n  static const pop = Duration(milliseconds: 140);\n  static const sheet = Duration(milliseconds: 220);\n  static const toast = Duration(milliseconds: 180);\n  static const toastStay = Duration(milliseconds: 2400);\n  static const popCurve = Cubic(0.2, 0.9, 0.3, 1.15);\n  static const sheetCurve = Cubic(0.22, 1, 0.36, 1);\n  /// Respect \"reduce motion\": MediaQuery.of(context).disableAnimations → Duration.zero\n  static Duration of(BuildContext c, Duration d) => MediaQuery.of(c).disableAnimations ? Duration.zero : d;\n}\n\n// ───────────────────────── Type ─────────────────────────\nclass BinGiType {\n  BinGiType._();\n  static const body = 'Instrument Sans';\n  static const heading = 'Bricolage Grotesque';\n  static const bangla = ['Hind Siliguri'];\n  static const pageTitle = TextStyle(fontFamily: heading, fontFamilyFallback: bangla, fontSize: 24, fontWeight: FontWeight.w700, height: 1.25, letterSpacing: -0.24, color: BinGiColors.ink);\n  static const section = TextStyle(fontFamily: heading, fontFamilyFallback: bangla, fontSize: 18, fontWeight: FontWeight.w700, height: 1.3, color: BinGiColors.ink);\n  static const cardTitle = TextStyle(fontFamily: body, fontFamilyFallback: bangla, fontSize: 17, fontWeight: FontWeight.w700, height: 1.3, color: BinGiColors.ink);\n  static const number = TextStyle(fontFamily: body, fontSize: 22, fontWeight: FontWeight.w700, height: 1.15, color: BinGiColors.ink, fontFeatures: [FontFeature.tabularFigures()]);\n  static const bodyText = TextStyle(fontFamily: body, fontFamilyFallback: bangla, fontSize: 14, height: 1.5, color: BinGiColors.ink);\n  static const bodyStrong = TextStyle(fontFamily: body, fontFamilyFallback: bangla, fontSize: 14.5, fontWeight: FontWeight.w600, height: 1.4, color: BinGiColors.ink);\n  static const label = TextStyle(fontFamily: body, fontFamilyFallback: bangla, fontSize: 13.5, fontWeight: FontWeight.w600, height: 1.3, color: BinGiColors.ink);\n  static const meta = TextStyle(fontFamily: body, fontFamilyFallback: bangla, fontSize: 12.5, fontWeight: FontWeight.w500, height: 1.35, color: BinGiColors.muted);\n  static const overline = TextStyle(fontFamily: body, fontSize: 12, fontWeight: FontWeight.w600, height: 1.3, letterSpacing: 0.5, color: BinGiColors.muted);\n}\n\n// ───────────────────────── ThemeData ─────────────────────────\nclass BinGiTheme {\n  BinGiTheme._();\n  static ThemeData light() {\n    final scheme = ColorScheme.fromSeed(seedColor: BinGiColors.action).copyWith(\n      primary: BinGiColors.action, onPrimary: Colors.white,\n      secondary: BinGiColors.focus, onSecondary: Colors.white,\n      error: BinGiColors.dangerFg, surface: BinGiColors.surface, onSurface: BinGiColors.ink,\n      outline: BinGiColors.line, outlineVariant: BinGiColors.line,\n    );\n    final ctrl = RoundedRectangleBorder(borderRadius: BinGiRadius.all(BinGiRadius.control));\n    return ThemeData(\n      useMaterial3: true,\n      colorScheme: scheme,\n      scaffoldBackgroundColor: BinGiColors.canvas,\n      fontFamily: BinGiType.body,\n      fontFamilyFallback: BinGiType.bangla,\n      splashFactory: NoSplash.splashFactory, // calm: no ripples, pressed = scale/fill\n      textTheme: const TextTheme(\n        headlineSmall: BinGiType.pageTitle, titleLarge: BinGiType.section, titleMedium: BinGiType.cardTitle,\n        bodyMedium: BinGiType.bodyText, bodyLarge: BinGiType.bodyStrong, labelLarge: BinGiType.label, bodySmall: BinGiType.meta,\n      ),\n      appBarTheme: const AppBarTheme(backgroundColor: BinGiColors.surface, foregroundColor: BinGiColors.ink, elevation: 0, scrolledUnderElevation: 0, centerTitle: false, titleTextStyle: BinGiType.section),\n      cardTheme: CardThemeData(color: BinGiColors.surface, elevation: 0, margin: EdgeInsets.zero,\n        shape: RoundedRectangleBorder(borderRadius: BinGiRadius.all(BinGiRadius.card), side: const BorderSide(color: BinGiColors.line))),\n      dividerTheme: const DividerThemeData(color: BinGiColors.line, thickness: 1, space: 1),\n      outlinedButtonTheme: OutlinedButtonThemeData(style: OutlinedButton.styleFrom(\n        minimumSize: const Size(0, BinGiSize.buttonMain), padding: const EdgeInsets.symmetric(horizontal: 16),\n        foregroundColor: BinGiColors.ink, backgroundColor: BinGiColors.surface, side: const BorderSide(color: BinGiColors.line),\n        shape: ctrl, textStyle: BinGiType.bodyStrong)),\n      textButtonTheme: TextButtonThemeData(style: TextButton.styleFrom(foregroundColor: BinGiColors.redText, textStyle: BinGiType.label, shape: ctrl)),\n      inputDecorationTheme: InputDecorationTheme(\n        filled: true, fillColor: BinGiColors.surface, isDense: true,\n        contentPadding: const EdgeInsets.symmetric(horizontal: 12, vertical: 12),\n        hintStyle: BinGiType.bodyText.copyWith(color: BinGiColors.muted),\n        border: OutlineInputBorder(borderRadius: BinGiRadius.all(BinGiRadius.input), borderSide: const BorderSide(color: BinGiColors.line)),\n        enabledBorder: OutlineInputBorder(borderRadius: BinGiRadius.all(BinGiRadius.input), borderSide: const BorderSide(color: BinGiColors.line)),\n        focusedBorder: OutlineInputBorder(borderRadius: BinGiRadius.all(BinGiRadius.input), borderSide: const BorderSide(color: BinGiColors.action, width: 1.5)),\n        errorBorder: OutlineInputBorder(borderRadius: BinGiRadius.all(BinGiRadius.input), borderSide: const BorderSide(color: BinGiColors.dangerFg)),\n      ),\n      chipTheme: ChipThemeData(backgroundColor: BinGiColors.surface, selectedColor: BinGiColors.soft, labelStyle: BinGiType.label,\n        side: const BorderSide(color: BinGiColors.line), shape: RoundedRectangleBorder(borderRadius: BinGiRadius.all(BinGiRadius.pill)), showCheckmark: false),\n      tabBarTheme: const TabBarThemeData(labelColor: BinGiColors.action, unselectedLabelColor: BinGiColors.muted, indicatorColor: BinGiColors.action,\n        labelStyle: TextStyle(fontSize: 14.5, fontWeight: FontWeight.w600), dividerColor: BinGiColors.line),\n      navigationBarTheme: NavigationBarThemeData(backgroundColor: BinGiColors.surface, height: BinGiSize.tabBar, elevation: 0,\n        indicatorColor: BinGiColors.soft, labelTextStyle: WidgetStateProperty.all(BinGiType.meta.copyWith(fontWeight: FontWeight.w600))),\n      bottomSheetTheme: const BottomSheetThemeData(backgroundColor: BinGiColors.surface, showDragHandle: true,\n        shape: RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(BinGiRadius.sheet)))),\n      snackBarTheme: SnackBarThemeData(backgroundColor: BinGiColors.toast, contentTextStyle: BinGiType.bodyText.copyWith(color: Colors.white, fontWeight: FontWeight.w500),\n        behavior: SnackBarBehavior.floating, shape: RoundedRectangleBorder(borderRadius: BinGiRadius.all(BinGiRadius.control))),\n      switchTheme: SwitchThemeData(trackColor: WidgetStateProperty.resolveWith((s) => s.contains(WidgetState.selected) ? BinGiColors.action : const Color(0xFFD3D8DF)),\n        thumbColor: WidgetStateProperty.all(Colors.white), trackOutlineColor: WidgetStateProperty.all(Colors.transparent)),\n      checkboxTheme: CheckboxThemeData(fillColor: WidgetStateProperty.resolveWith((s) => s.contains(WidgetState.selected) ? BinGiColors.action : Colors.transparent),\n        side: const BorderSide(color: BinGiColors.control, width: 1.5), shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(4))),\n      progressIndicatorTheme: const ProgressIndicatorThemeData(color: BinGiColors.focus, linearTrackColor: BinGiColors.track),\n      pageTransitionsTheme: const PageTransitionsTheme(builders: {\n        TargetPlatform.android: _FadeOnly(), TargetPlatform.iOS: _FadeOnly(),\n      }),\n    );\n  }\n}\n\n/// Page change = 150 ms fade. No zoom, no slide (owner's rule, 12 Nov).\nclass _FadeOnly extends PageTransitionsBuilder {\n  const _FadeOnly();\n  @override\n  Widget buildTransitions<T>(PageRoute<T> route, BuildContext context, Animation<double> a, Animation<double> s, Widget child) =>\n      FadeTransition(opacity: CurvedAnimation(parent: a, curve: Curves.easeOut), child: child);\n  @override\n  Duration get transitionDuration => BinGiMotion.page;\n}\n\n// ───────────────────────── Components ─────────────────────────\n\n/// One red main action per screen (live-HMS button): gradient + soft red shadow, 44 px, 12 px corners.\nclass BinGiPrimaryButton extends StatefulWidget {\n  const BinGiPrimaryButton({super.key, required this.label, this.icon, this.onPressed, this.expand = false, this.height = BinGiSize.buttonMain});\n  final String label; final IconData? icon; final VoidCallback? onPressed; final bool expand; final double height;\n  @override State<BinGiPrimaryButton> createState() => _BinGiPrimaryButtonState();\n}\nclass _BinGiPrimaryButtonState extends State<BinGiPrimaryButton> {\n  bool _down = false;\n  @override\n  Widget build(BuildContext context) {\n    final on = widget.onPressed != null;\n    final child = Row(mainAxisSize: widget.expand ? MainAxisSize.max : MainAxisSize.min, mainAxisAlignment: MainAxisAlignment.center, children: [\n      if (widget.icon != null) ...[Icon(widget.icon, size: 18, color: Colors.white), const SizedBox(width: 8)],\n      Flexible(child: Text(widget.label, maxLines: 1, overflow: TextOverflow.ellipsis, style: BinGiType.bodyStrong.copyWith(color: Colors.white))),\n    ]);\n    return Semantics(button: true, enabled: on, child: GestureDetector(\n      onTapDown: on ? (_) => setState(() => _down = true) : null,\n      onTapCancel: () => setState(() => _down = false),\n      onTapUp: on ? (_) { setState(() => _down = false); widget.onPressed!(); } : null,\n      child: AnimatedScale(scale: _down ? .985 : 1, duration: BinGiMotion.of(context, BinGiMotion.press),\n        child: AnimatedOpacity(opacity: on ? 1 : .45, duration: BinGiMotion.press, child: Container(\n          height: widget.height, padding: const EdgeInsets.symmetric(horizontal: 20), alignment: Alignment.center,\n          decoration: BoxDecoration(gradient: BinGiColors.actionGradient, borderRadius: BinGiRadius.all(BinGiRadius.button), boxShadow: on ? BinGiShadow.action : null),\n          child: child))),\n    ));\n  }\n}\n\n/// Everything else: white, 1 px line border, ink text.\nclass BinGiSecondaryButton extends StatelessWidget {\n  const BinGiSecondaryButton({super.key, required this.label, this.icon, this.onPressed, this.height = BinGiSize.buttonMain});\n  final String label; final IconData? icon; final VoidCallback? onPressed; final double height;\n  @override\n  Widget build(BuildContext context) => OutlinedButton.icon(onPressed: onPressed, icon: icon == null ? const SizedBox.shrink() : Icon(icon, size: 18),\n    label: Text(label), style: OutlinedButton.styleFrom(minimumSize: Size(0, height)));\n}\n\nenum BinGiTone { info, success, warning, danger, violet, neutral }\n({Color bg, Color fg}) binGiTone(BinGiTone t) => switch (t) {\n  BinGiTone.info => (bg: BinGiColors.infoBg, fg: BinGiColors.infoFg),\n  BinGiTone.success => (bg: BinGiColors.successBg, fg: BinGiColors.successFg),\n  BinGiTone.warning => (bg: BinGiColors.warningBg, fg: BinGiColors.warningFg),\n  BinGiTone.danger => (bg: BinGiColors.dangerBg, fg: BinGiColors.dangerFg),\n  BinGiTone.violet => (bg: BinGiColors.violetBg, fg: BinGiColors.violetFg),\n  BinGiTone.neutral => (bg: BinGiColors.neutralBg, fg: BinGiColors.neutralFg),\n};\n\n/// Status pill: 6 px corners, dot + label. Booking status, payment, room readiness and maintenance stay separate pills.\nclass BinGiStatusPill extends StatelessWidget {\n  const BinGiStatusPill(this.label, {super.key, this.tone = BinGiTone.neutral, this.dot = true});\n  final String label; final BinGiTone tone; final bool dot;\n  @override\n  Widget build(BuildContext context) {\n    final c = binGiTone(tone);\n    return Container(padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),\n      decoration: BoxDecoration(color: c.bg, borderRadius: BinGiRadius.all(BinGiRadius.chip)),\n      child: Row(mainAxisSize: MainAxisSize.min, children: [\n        if (dot) ...[Container(width: 6, height: 6, decoration: BoxDecoration(color: c.fg, shape: BoxShape.circle)), const SizedBox(width: 6)],\n        Text(label, style: BinGiType.meta.copyWith(color: c.fg, fontWeight: FontWeight.w600)),\n      ]));\n  }\n}\n\n/// Segmented control (live HMS): white box, 1 px border; selected = soft red bg + red text.\nclass BinGiSegmented<T> extends StatelessWidget {\n  const BinGiSegmented({super.key, required this.items, required this.value, required this.onChanged});\n  final List<(T, String)> items; final T value; final ValueChanged<T> onChanged;\n  @override\n  Widget build(BuildContext context) => Container(\n    padding: const EdgeInsets.all(4),\n    decoration: BoxDecoration(color: BinGiColors.surface, border: Border.all(color: BinGiColors.line), borderRadius: BinGiRadius.all(BinGiRadius.control)),\n    child: Row(mainAxisSize: MainAxisSize.min, children: [for (final (v, l) in items)\n      Semantics(selected: v == value, button: true, child: GestureDetector(onTap: () => onChanged(v), child: AnimatedContainer(\n        duration: BinGiMotion.of(context, BinGiMotion.press), height: 36, padding: const EdgeInsets.symmetric(horizontal: 12), alignment: Alignment.center,\n        decoration: BoxDecoration(color: v == value ? BinGiColors.soft : Colors.transparent, borderRadius: BinGiRadius.all(10)),\n        child: Text(l, style: BinGiType.label.copyWith(color: v == value ? BinGiColors.action : BinGiColors.muted)))))]));\n}\n\n/// Card: white, 1 px line border, 20 px corners, no shadow.\nclass BinGiCard extends StatelessWidget {\n  const BinGiCard({super.key, required this.child, this.padding = const EdgeInsets.all(16), this.selected = false, this.onTap});\n  final Widget child; final EdgeInsets padding; final bool selected; final VoidCallback? onTap;\n  @override\n  Widget build(BuildContext context) => Material(color: BinGiColors.surface, borderRadius: BinGiRadius.all(BinGiRadius.card),\n    child: InkWell(onTap: onTap, borderRadius: BinGiRadius.all(BinGiRadius.card), child: Container(padding: padding,\n      decoration: BoxDecoration(borderRadius: BinGiRadius.all(BinGiRadius.card), border: Border.all(color: selected ? BinGiColors.softBorder : BinGiColors.line)),\n      child: child)));\n}\n\n/// Number tile (dashboard / module top): icon in tinted 44 px square, label, big number, optional sub line.\nclass BinGiStatTile extends StatelessWidget {\n  const BinGiStatTile({super.key, required this.icon, required this.label, required this.value, this.sub, this.tone = BinGiTone.info, this.onTap, this.selected = false});\n  final IconData icon; final String label, value; final String? sub; final BinGiTone tone; final VoidCallback? onTap; final bool selected;\n  @override\n  Widget build(BuildContext context) {\n    final c = binGiTone(tone);\n    return BinGiCard(onTap: onTap, selected: selected, child: Row(children: [\n      Container(width: 44, height: 44, decoration: BoxDecoration(color: c.bg, borderRadius: BinGiRadius.all(BinGiRadius.tile)), child: Icon(icon, size: 20, color: c.fg)),\n      const SizedBox(width: 12),\n      Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [\n        Text(label, style: BinGiType.meta), Text(value, style: BinGiType.number, maxLines: 1, overflow: TextOverflow.ellipsis),\n        if (sub != null) Text(sub!, style: BinGiType.meta.copyWith(fontSize: 12)),\n      ])),\n    ]));\n  }\n}\n\n/// One-line banner: amber (needs attention), blue (in progress), green (done).\nclass BinGiBanner extends StatelessWidget {\n  const BinGiBanner(this.text, {super.key, this.kind = BinGiBannerKind.amber, this.icon, this.action});\n  final String text; final BinGiBannerKind kind; final IconData? icon; final Widget? action;\n  @override\n  Widget build(BuildContext context) {\n    final (bg, line, fg) = switch (kind) {\n      BinGiBannerKind.amber => (BinGiColors.amberBg, BinGiColors.amberLine, BinGiColors.amberFg),\n      BinGiBannerKind.blue => (BinGiColors.blueBg, BinGiColors.blueLine, BinGiColors.blueFg),\n      BinGiBannerKind.green => (BinGiColors.greenBg, BinGiColors.greenLine, BinGiColors.greenFg),\n    };\n    return Container(padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 12),\n      decoration: BoxDecoration(color: bg, border: Border.all(color: line), borderRadius: BinGiRadius.all(BinGiRadius.tile)),\n      child: Row(children: [\n        if (icon != null) ...[Icon(icon, size: 18, color: fg), const SizedBox(width: 10)],\n        Expanded(child: Text(text, style: BinGiType.bodyText.copyWith(color: fg))),\n        if (action != null) action!,\n      ]));\n  }\n}\nenum BinGiBannerKind { amber, blue, green }\n\n/// Avatar with initials (soft red), or dashed empty \"not assigned\".\nclass BinGiAvatar extends StatelessWidget {\n  const BinGiAvatar({super.key, this.name, this.size = BinGiSize.avatar});\n  final String? name; final double size;\n  @override\n  Widget build(BuildContext context) {\n    final n = name;\n    final ini = n == null ? '' : n.trim().split(RegExp(r'\\s+')).take(2).map((p) => p.isEmpty ? '' : p[0]).join().toUpperCase();\n    return Container(width: size, height: size, alignment: Alignment.center,\n      decoration: BoxDecoration(color: n == null ? Colors.transparent : BinGiColors.soft, shape: BoxShape.circle,\n        border: n == null ? Border.all(color: BinGiColors.lineStrong) : null),\n      child: n == null ? Icon(Icons.person_outline, size: size * .45, color: BinGiColors.muted)\n        : Text(ini, style: TextStyle(fontSize: size * .33, fontWeight: FontWeight.w700, color: BinGiColors.action)));\n  }\n}\n\n/// Toast: dark, white text, green check — 2.4 s.\nvoid showBinGiToast(BuildContext context, String text) {\n  ScaffoldMessenger.of(context)\n    ..hideCurrentSnackBar()\n    ..showSnackBar(SnackBar(duration: BinGiMotion.toastStay, content: Row(children: [\n      const Icon(Icons.check_circle, size: 16, color: Color(0xFF7EE2A8)), const SizedBox(width: 8), Expanded(child: Text(text)),\n    ])));\n}\n"},
  {"path": "README.md", "label": "Guide (Bangla)", "lang": "md", "body": "# BinGi HMS — Design Foundation v1\n\n**তারিখ:** ১৯ নভেম্বর ২০২৬\n**উৎস:** HMS web prototype (repo `BINGI-WEB-theme-`, commit `c994c50`) — BinGi Pearl রং + live HMS-এর button foundation (১২ নভেম্বর)।\n**কাজে লাগবে:** HMS web, Mobile HMS app (Flutter), Guest App — সব জায়গায় এক রকম দেখাতে।\n**Hotel website theme-এ লাগবে না** — প্রতিটা hotel নিজের brand রং রাখে।\n\n## ফাইল\n\n| ফাইল | কী |\n|---|---|\n| `tokens/bingi-hms.tokens.json` | সব token (W3C Design Tokens format) — যেকোনো tool/platform-এ convert করা যায় |\n| `flutter/lib/bingi_theme.dart` | Flutter: `BinGiColors`, `BinGiType`, `BinGiRadius`, `BinGiSpace`, `BinGiShadow`, `BinGiMotion`, `BinGiTheme.light()` + ready widget: Primary/Secondary button, StatusPill, Segmented, Card, StatTile, Banner, Avatar, Toast |\n| `web/bingi-hms.css` | Plain CSS variables + component class (`.bh-btn--main`, `.bh-pill--success`, `.bh-seg` …) |\n| `web/tailwind-theme.css` | Tailwind v4 `@theme` — HMS web prototype-এর একই নাম (`hms-*`) |\n| `react/bingi-ui.tsx` | React + Tailwind v4 component: `MainButton`, `Button`, `StatusPill` + `STATUS_TONE`, `Segmented`, `Tabs`, `Card`, `StatTile`, `Banner`, `Avatar`, `Progress`, `useToast` — Mobile HMS (React prototype) এর জন্য |\n| `preview.html` | সব token আর component এক পাতায় দেখার জন্য (browser-এ খুলুন) |\n\n### React / Mobile HMS-এ বসানো (৩ ধাপ)\n1. `src/index.css`: `@import \"tailwindcss\";` তারপর `tailwind-theme.css` এর পুরো লেখা paste করুন।\n2. Font: Instrument Sans, Bricolage Grotesque, Hind Siliguri (`@fontsource-variable/*` বা Google Fonts)।\n3. `bingi-ui.tsx` → `src/ui/` এ কপি করুন — `<MainButton>Check in</MainButton>`, `<StatusPill tone={STATUS_TONE[\"In house\"]}>In house</StatusPill>`।\n\n### Flutter-এ বসানো (৩ ধাপ)\n1. `bingi_theme.dart` → `lib/theme/` এ কপি করুন।\n2. Font যোগ করুন (`pubspec.yaml`): Instrument Sans, Bricolage Grotesque, Hind Siliguri (অথবা `google_fonts` package)।\n3. `MaterialApp(theme: BinGiTheme.light(), …)` — এরপর `BinGiPrimaryButton(label: 'Check in', onPressed: …)`, `BinGiStatusPill('In house', tone: BinGiTone.success)` ইত্যাদি।\nFlutter 3.27+ লাগবে (`CardThemeData`, `TabBarThemeData`)। এই ফাইল এখানে compile করা হয়নি (Flutter SDK নেই) — প্রথমবার `flutter analyze` চালিয়ে নিন।\n\n---\n\n## ১. মূল নিয়ম (সব প্ল্যাটফর্মে)\n1. **এক স্ক্রিনে একটাই লাল main button।** বাকি সব সাদা, ১px border।\n2. **লাল কম ব্যবহার।** লাল = action বা selected; error-এর জন্য আলাদা danger রং (#B42318)।\n3. **Card flat:** সাদা, ১px border #E3E7EC, ২০px কোণা, shadow নেই। Card-এর ভেতরে card না।\n4. **কোণা:** button/input/segment ১২px · tile ১৬px · card ২০px · sheet ২৪px · status pill ৬px · chip/pill ৯৯৯px।\n5. **উচ্চতা:** main button ও input ৪৪px · row-এর ভেতরের button ৩৬px · tap target কমপক্ষে ৪৪px।\n6. **Focus ring নীল (#1D4ED8)** — লাল না, যাতে error মনে না হয়।\n7. **Animation শান্ত:** page বদল = শুধু ১৫০ms fade (zoom/slide না)। Button চাপলে ০.৯৮৫ scale। Reduce motion চালু থাকলে কোনো animation না।\n8. **Status আলাদা রাখুন:** booking status, payment, room readiness, maintenance — প্রতিটা নিজের pill, কখনো এক pill-এ মেশাবেন না।\n9. **ভাষা:** Bangla + English; Bangla font Hind Siliguri fallback। তারিখ লিখুন \"Tue 10 Nov\" (11/10/2026 না)।\n\n## ২. রং\n\n### Brand / action\n| Token | Hex | কোথায় |\n|---|---|---|\n| action | `#C8232E` | main button (gradient-এর মাঝ), active tab/segment-এর লেখা |\n| action gradient | `#D22C35 → #C8232E → #BA1F2B` (উপর থেকে নিচে) | main button; shadow `0 6px 16px rgba(200,35,46,.24)` |\n| action hover | `#A81C27` | main button hover/pressed |\n| red-text | `#B11C29` | সাদা background-এ লাল লেখা ও link (৬.৮৫:১) |\n| soft | `#FFECEC` | selected segment / active filter background |\n| soft-2 | `#FFF6F6` | selected tile/row background |\n| soft-border | `#F3C4C0` | selected card-এর border |\n| blush | `#FFE7E4` | avatar, ছোট accent chip |\n| logo coral | `#FD413F` | শুধু logo / বড় art — ছোট লেখায় কখনো না |\n\n### Neutral\n| Token | Hex | কোথায় |\n|---|---|---|\n| canvas | `#F4F6F8` | app background |\n| surface | `#FFFFFF` | card, sheet, input, sidebar |\n| surface-alt | `#FAFAFB` | table header |\n| ink | `#0F1720` | মূল লেখা |\n| muted | `#4D5664` | দ্বিতীয় লেখা (৭.৪:১) |\n| hover | `#E9EDF2` | hover/pressed fill |\n| track | `#EEF0F3` | progress track, neutral pill |\n| line | `#E3E7EC` | border, divider |\n| line-strong | `#C9CED6` | hovered card border |\n| control | `#858C97` | যেখানে ৩:১ input border দরকার |\n\n### Status (background / লেখা) — সব module-এ একই অর্থ\n| Tone | bg | fg | উদাহরণ |\n|---|---|---|---|\n| info | `#E8F0FE` | `#1D4ED8` | Confirmed · Cleaning · Website |\n| success | `#E5F5EC` | `#16693A` | In house · Paid · Ready · Room clean |\n| warning | `#FDF3D9` | `#7A4A0B` | Pending · Partly paid · Guest arriving |\n| danger | `#FDECEC` | `#B42318` | Due · Cancelled · No-show · Overdue · High |\n| violet | `#F1EDFF` | `#5B45C9` | Awaiting inspection · Refund due · OTA |\n| neutral | `#EEF0F3` | `#4D5664` | Checked out · Low · Walk-in |\n| orange (শুধু লেখা) | — | `#C2410C` | Needs cleaning · Leaves today |\n\nHousekeeping step dot: Pending `#D97706` · Cleaning `#2563EB` · Inspection `#6D5BD0` · Ready `#16A34A`।\nBanner: amber (দেখা দরকার) `#FDF8EC / #F1DFB8 / #6B4309` · blue (চলছে) `#EEF3FD / #CFDCF7 / #1E3A8A` · green (শেষ) `#EEF8F2 / #CDE9D8 / #14532D`।\nChart: `#B11C29 · #1D4ED8 · #0E9F6E · #F59E0B · #0B2235`।\n\n## ৩. লেখা (Type)\nBody: **Instrument Sans** · Heading (h1–h3): **Bricolage Grotesque**, letter-spacing −0.02em · Bangla: **Hind Siliguri**।\n\n| Style | সাইজ / weight | কোথায় |\n|---|---|---|\n| page-title | 24 / 700 | পাতার শিরোনাম |\n| section | 18 / 700 | section শিরোনাম |\n| card-title | 17 / 700 | \"Room 203\" |\n| number | 22 / 700, tabular | সংখ্যার tile |\n| body | 14 / 400 | সাধারণ লেখা |\n| body-strong | 14.5 / 600 | button, নাম |\n| label | 13.5 / 600 | tab, segment, ছোট button |\n| meta | 12.5 / 500, muted | সময়, কোড, নিচের লাইন |\n| overline | 12 / 600, uppercase | \"TEAM NOW\" |\n\nটাকা: `৳4,500` (tabular figures)। বাংলা সংখ্যা UI-তে Bangla mode-এ।\n\n## ৪. Spacing\n4 · 8 · 12 · 16 · 20 · 24 · 32 · 40px। Page padding: phone ১৬px, desktop ২৪px। Card padding ১৬px। Card-এর মাঝে ১২px gap।\n\n## ৫. Component (web prototype-এ যেমন আছে)\n\n| Component | Spec |\n|---|---|\n| **Main button** | ৪৪px, ১২px কোণা, red gradient + soft red shadow, সাদা ১৪.৫/৬০০ লেখা, icon ১৮px বাঁয়ে; চাপলে ০.৯৮৫; disabled ৪৫% opacity, shadow নেই |\n| **Secondary button** | ৪৪px, সাদা, ১px line border, ink লেখা; hover #E9EDF2 |\n| **Row button** | ৩৬px, ১৩.৫/৬০০ — টেবিল/কার্ডের ভেতরে (\"View task\", \"Open\") |\n| **Segmented / view toggle** | সাদা বাক্স + ১px border, ৪px padding; selected = #FFECEC bg + #C8232E লেখা (Cards/List, Easy/Advanced) |\n| **Underline tabs** | ১৪.৫/৬০০ muted; selected = লাল লেখা + ২px লাল underline (Tasks · Maintenance · Checklist) |\n| **Status tabs with count** | selected = লাল ভরা pill + সাদা লেখা \"All (49)\" |\n| **Card** | সাদা, ১px line, ২০px; selected border #F3C4C0 |\n| **Stat tile** | card + ৪৪px tinted icon square (১৬px কোণা), label (meta), সংখ্যা ২২/৭০০, নিচে ছোট লাইন; চাপলে filter |\n| **Status strip** | এক card-এ ৪ ভাগ (Pending · Cleaning · Awaiting inspection · Ready), প্রতিটায় icon + নাম + সংখ্যা; selected bg #FFF6F6 |\n| **Status pill** | ৬px কোণা, ৬px dot + ১২.৫/৬০০, tone অনুযায়ী রং |\n| **Input / select** | ৪৪px, ১২px, সাদা, ১px line; focus border লাল; search-এ বাঁয়ে ১৬px icon |\n| **Banner** | ১৬px কোণা, ১px border, icon + এক লাইন; amber / blue / green |\n| **Avatar** | গোল, soft red bg + লাল initials; না থাকলে dashed border + person icon (\"Not assigned\") |\n| **Progress** | ৬px উচু, track #EEF0F3, fill #1D4ED8, গোল |\n| **Toast** | কালো (#0F1720), সাদা লেখা, সবুজ ✓, নিচে মাঝে, ২.৪ সেকেন্ড |\n| **Side panel / bottom sheet** | সাদা, ২৪px উপরের কোণা (phone), footer-এ Close + main action |\n| **Menu / popover** | সাদা, ১৬px, ১px line, float shadow, ১৪০ms pop |\n| **Switch** | on = #C8232E, off = #D3D8DF |\n| **Empty state** | card-এর মাঝে ৪৮px tinted icon, ১৬/৬০০ শিরোনাম, ১৪ muted এক লাইন |\n\n## ৬. Motion\n| কী | সময় | কেমন |\n|---|---|---|\n| Page বদল | 150ms ease-out | শুধু opacity fade |\n| Button চাপা | 120ms | scale 0.985 |\n| Menu/popover | 140ms `cubic-bezier(.2,.9,.3,1.15)` | opacity + ৪px নামা |\n| Sheet / side panel | 220ms `cubic-bezier(.22,1,.36,1)` | নিচ/ডান থেকে slide |\n| Toast | 180ms | ১২px উঠে fade, ২.৪s থাকে |\n| Reduce motion | — | কোনো animation না |\n\n## ৭. Mobile HMS-এর জন্য (Mobile_HMS_Design_Plan_v1 থেকে)\n- Header ছোট: শিরোনাম + ১টা action; system banner এক লাইনের toast।\n- Stepper: \"Step 1 of 4 · Rooms & rates\"।\n- সংখ্যা এক লাইনের chip row; team = avatar strip; filter bottom sheet-এ।\n- POS: নিচে cart bar → full-screen cart sheet; tab শুধু Tables · Orders · Kitchen।\n- Kitchen: ৩ column → segmented tab with count।\n- Bottom tab bar role অনুযায়ী (owner / reception / housekeeping / restaurant); ৬৪px, selected = soft red indicator।\n\n## ৮. যা বদলানো যাবে না\n- Logo শুধু `brand/` ফোল্ডারের official ফাইল — আঁকা বা বদলানো না।\n- লাল main action এক স্ক্রিনে একটার বেশি না।\n- Booking status / payment / room readiness / maintenance এক জায়গায় মেশানো না।\n- Dark mode এখন শুধু KDS-এর জন্য (ঠিক করা হয়নি বাকি জায়গায়)।\n\n## খোলা প্রশ্ন\n- **Primary লাল:** Pearl token-এ #B11C29, live HMS button-এ #C8232E। এই foundation-এ: button/selected = #C8232E, লাল লেখা ও link = #B11C29 (বেশি contrast)। একটাই রাখতে চাইলে বলুন।\n"},
];
